"""Original Build C teaching, local formative checks and public reference metadata.

Checks are ungraded learning aids; they never award persisted practice or game credit.
Older question editions retain their original metadata in cyber_content.
"""
REVIEW_DATE = '2026-10-29'
OWASP_ROOT = 'https://cheatsheetseries.owasp.org/cheatsheets/'
APP_READINGS = {
 'session': ('Session Management', 'Session_Management_Cheat_Sheet.html'),
 'password': ('Password Storage', 'Password_Storage_Cheat_Sheet.html'),
 'csrf': ('Cross-Site Request Forgery Prevention', 'Cross-Site_Request_Forgery_Prevention_Cheat_Sheet.html'),
 'ssrf': ('Server Side Request Forgery Prevention', 'Server_Side_Request_Forgery_Prevention_Cheat_Sheet.html'),
 'upload': ('File Upload', 'File_Upload_Cheat_Sheet.html'),
 'deserialize': ('Deserialization', 'Deserialization_Cheat_Sheet.html'),
 'csp': ('Content Security Policy', 'Content_Security_Policy_Cheat_Sheet.html'),
 'logging': ('Logging', 'Logging_Cheat_Sheet.html'),
}
# One reference covers the decision's specific subject, rather than a generic homepage.
APP_SOURCE_BY_NUMBER = dict(enumerate([
 'session', 'session', 'session', 'password', 'password', 'csrf', 'ssrf', 'upload',
 'deserialize', 'csp', 'upload', 'upload', 'upload', 'session', 'logging', 'ssrf',
 'csrf', 'password', 'upload', 'ssrf', 'deserialize', 'csp', 'upload', 'session', 'upload'
], start=26))


def app_source(number):
    title, path = APP_READINGS[APP_SOURCE_BY_NUMBER[number]]
    return {'title': 'OWASP: ' + title, 'url': OWASP_ROOT + path, 'reviewed': REVIEW_DATE}


# Three short explanations per topic introduce terms before the worked decisions.
TEACHING = {
 'fundamentals': [
 ('Describe what matters', 'An asset is information, a system or another resource with value. An owner connects it to a business purpose. A threat event may be deliberate or accidental; a vulnerability is a weakness through which harm can occur. Start with the service and its dependencies, then describe a plausible event and consequence. Do not confuse a weakness with evidence that the event already happened.'),
 ('Match protection to purpose', 'Classification guides handling according to sensitivity and intended use. Data minimisation means collecting and retaining what is justified, rather than everything that might someday be useful. Preventive controls reduce an event or access path; detective controls reveal activity; corrective controls help restore or repair. Physical protection and synthetic test data address different exposure paths. Non-repudiation supports disputes about origin or action using evidence whose custody and interpretation still matter.'),
 ('Make a bounded decision', 'Security by design considers authority, threats and failure modes before release. Compare treatments against business tolerances, including tradeoffs between frequency and impact or recovery time. A powerful management relationship can make an otherwise ordinary system critical. Shared control dependencies, uncertainty in loss estimates and changing measurement scope belong in the analysis. Record the decision authority and revisit it when assumptions change.')],
 'phishing': [
 ('Recognise the request, not just the channel', 'Spear phishing targets a person or group. Smishing uses text messages, while voice calls, QR codes, chat and shared-document services can carry similar deception. A pretext is the persuasive story: a delivery fee, recruitment step, support ticket or urgent executive instruction. A real account, authenticated sending domain or familiar hosting service does not prove the requested business action is authorised.'),
 ('Break the attacker-controlled loop', 'For a consequential request, stop and use an independently known service or contact route. Refreshing the same link or calling the number in the message does not create independence. Protect one-time codes and avoid lending an authenticated session to an unverified person. Verify the need before sharing identity documents. A convincing voice or profile image should not bypass transaction approval.'),
 ('Report the interaction accurately', 'Tell responders whether a message was received, a file downloaded, input submitted, consent granted or a session possibly exposed. A page can capture a password and then display a failure. Application consent may grant access separately from a password. Use approved reporting; do not copy work files to personal mailboxes or place credentials in tickets. A blocked link for one person does not establish the campaign outcome for everyone.')],
 'identity': [
 ('Separate identity, proof and permission', 'A passphrase is a type of password. A protected password manager can help maintain distinct credentials. Authentication factors belong to categories such as knowledge and possession; two passwords are both knowledge. Federation lets a service trust defined identity-provider assertions, but signature, issuer, audience and transaction context still need validation. Throttling limits repeated attempts and should be designed with availability in mind.'),
 ('Manage the whole lifecycle', 'Joiner, mover and leaver processes should keep authority aligned with current duties. Roles organise permissions; nested groups and control over a privileged group can create indirect access. Service identities need owners and scoped grants too. Prefer separate identities where two applications need different authority. Recovery codes, reset links and access tokens are secrets, even in screenshots. A reset token needs account binding, limited life and appropriate single-use behaviour.'),
 ('Validate sensitive transitions', 'Fresh re-authentication can protect a sensitive account change; it does not justify changing someone else’s record. Reset responses should avoid unnecessary account-existence disclosure. Credential stuffing uses leaked credentials across services, so reuse increases exposure. Review delegated access and independent API tokens during response. Password changes and a local logout animation do not automatically invalidate every server session. Emergency access needs protected custody, monitoring and tested availability.')],
 'network': [
 ('Learn the path', 'Routing chooses paths between networks. A subnet groups addresses; a transport port identifies a logical service endpoint. Zones express communication and protection requirements. A VPN protects a tunnel within its design, while a proxy intermediates requests within its configured scope. Neither grants unlimited trust or business permission. Inventory and naming records help connect observations to managed assets.'),
 ('Enforce the intended boundary', 'Define required sources, destinations and services for guest, supplier, application and administration access. Review the effective path: a correct policy on the wrong interface may not control the intended traffic. In first-match rules, an earlier broad allow can make a later deny irrelevant. Check alternative interfaces and privileged management paths that can change the policy. Isolation labels require validation across relevant connectivity.'),
 ('Measure with context', 'Latency is delay; packet loss is delivery failure, neither of which alone proves an attack. Flow records summarise observed communications rather than every message byte or human intent. Address translation can combine hosts behind one public address, so attribution needs mapping and time context. Redundant links can share a physical duct. Test service dependencies and rollback while balancing urgent containment against avoidable disruption.')],
 'endpoint': [
 ('Protect more than the desktop', 'Endpoint scope can include phones, printers and appliances that store data or expose services. Secure boot checks supported startup components against a trust policy; firmware needs its own trusted maintenance. Disk encryption protects stored data within its model, not every action in an unlocked session. Locking and inactivity timeouts reduce unattended access. Recovery keys need protected custody and usable authorised recovery.'),
 ('Control software and device authority', 'A security baseline states expected settings. Restrict unused services and remote-support agents, obtain software through trusted channels, and review browser-extension and mobile-app permissions. Allowlisting limits permitted execution but cannot make every allowed program harmless. Updates and extensions introduce supply-chain trust paths. A personal device accessing work data needs explicit use, separation, support and privacy boundaries.'),
 ('Verify effective state', 'Downloading a patch is not the same as installing and activating it; a pending reboot may matter. Tool coverage and freshness affect reported state. Isolation can interrupt telemetry, so fewer alerts need careful interpretation. Test approved exceptions against actual deployed settings. At retirement, use a sanitisation method appropriate to the device and storage rather than assume a generic reset or deleted shortcut removes all data.')],
 'application': [
 ('Keep session authority under control', 'A session associates requests with an authenticated interaction. Cookies can carry session identifiers. Secure constrains cookie transport; HttpOnly restricts ordinary script access. Neither replaces permissions or all CSRF protection. Renew session identifiers at authentication where appropriate to prevent fixation. Idle and absolute lifetimes need server enforcement. Use an appropriate salted, deliberately expensive password hashing scheme; hashing is not reversible password storage.'),
 ('Separate data from behaviour', 'CSRF abuses automatically attached credentials to cause an unintended action. SSRF abuses the server’s ability to request other destinations, including through redirects. Constrain effective destinations and network reachability. Untrusted file paths must remain inside the permitted resolved boundary and require access authority. Avoid unsafe object deserialization; prefer constrained data formats and explicit fields. An authenticated client can still supply dangerous input.'),
 ('Use layers with explicit limits', 'For uploads, validate permitted content, control storage names and locations, avoid executable delivery and bound both compressed and expanded processing. A clean malware scan does not prove bounded parser work. An enforcing CSP limits covered browser behaviour; report-only mode observes rather than blocks. Safe rendering remains necessary. Logs need useful non-secret context with minimal personal data. Review the optional OWASP references for deeper implementation guidance.')],
 'cloud': [
 ('Locate the responsibility boundary', 'IaaS supplies infrastructure while the customer commonly manages the guest operating environment. SaaS supplies a provider-operated application with customer access and configuration duties. Managed databases split responsibilities differently again. Identify owners, region and actual service capabilities; a regional label or contract title does not prove legal compliance or recoverability. The linked 2011 NIST text is background, not current vendor setup guidance.'),
 ('Protect management and data separately', 'The control plane manages resources and permissions; the data plane serves workload data. Protect powerful console and cross-account trust paths. An obscure object name is not an access check. A signed URL can grant temporary scoped access, so operation and expiry matter. Development labels do not prevent production reads. Review logging contents for sensitive information as well as recording the events you need.'),
 ('Plan persistence and limits', 'Elasticity adjusts capacity but is subject to service limits and cost. Quotas can affect growth and recovery. Ephemeral disk may disappear with its instance; explicitly provide required persistence. Lifecycles govern retention and retirement, including credentials left behind after resource deletion. Correlate unusual costs with identities, changes and demand. Recovery needs appropriate regional and administrative independence and available decryption authority.')],
 'response': [
 ('Prepare decisions and communication', 'A playbook describes actions for a defined situation, supported by escalation thresholds, contact alternatives and decision authority. If corporate communication is affected, an authorised alternative route may be needed. Exercises should use reviewed safe boundaries; a destructive script does not become safe because a meeting is called a drill. Scope includes relevant systems, identities, data and uncertainties.'),
 ('Collect and interpret evidence', 'An indicator is a clue, not proof of every business impact. Record observations, sources and collection methods. Chain of custody tracks handling; integrity checks support comparison without proving the source was complete. Restrict evidence access and minimise sensitive screenshots. Separate current-state observations from historical reconstruction. Test competing explanations and reconcile clock, coverage and event-semantics differences.'),
 ('Test the operational chain', 'Detection requires more than a rule triggering: delivery, receipt and escalation must work. Tune false positives while checking that important true detections remain covered. For containment, distinguish requested, executed and effective. For eradication, address persistence and relevant re-entry. New evidence can expand scope. Restored availability is distinct from resolved security questions; approved updates should state facts, uncertainty and next decisions.')],
 'recovery': [
 ('Know what the copy represents', 'Retention defines how long copies are held. A full backup captures its defined whole; incrementals capture changes relative to a defined point and may depend on an intact chain. Label scope and recovery point. An offline copy is disconnected under its design; immutability protects defined retained states but does not ensure future copies will be made. Protect administration and recovery-key procedures.'),
 ('Recover the business service', 'Runbooks need available instructions, identities, keys, connectivity, application components and people. Business owners help validate data usefulness alongside technical checks. File extraction proves less than end-to-end operation. Failover switches to an alternate; failback returns to the primary and may require transaction reconciliation. Copies, identities and network paths can share failures even across sites.'),
 ('Compare evidence with targets', 'If a system fails at noon and the last usable point is 11:30, up to thirty minutes of changes may require recovery or reconciliation from other records. Restore duration is different from the data-loss window. Define which interval a time measure includes; do not present a restore-command interval as complete outage recovery. Report target misses, excluded dependencies, incomplete validation and alternate usable points explicitly.')],
 'governance': [
 ('Connect requirements to accountable action', 'Policy states direction; procedure describes execution. Control owners oversee operation, risk owners decide treatment, and independent assurance evaluates evidence. Criteria define the benchmark. Appetite guides broad risk choices while tolerance sets more specific limits. Breaches need escalation, decisions and follow-up. An agreed action can differ from a recommendation if it achieves a justified control outcome.'),
 ('Test a defensible population', 'Scope defines systems, period and questions. A sample is selected from a population; reconcile that population and avoid selecting only cases already marked successful. Report selection and inference limits. A finding separates observed condition from plausible implication; do not invent loss or intent. Declare conflicts and address self-review risks. Protect raw evidence as well as final reports.'),
 ('Follow dependencies and change', 'Supplier duties, audit rights and subcontracting need evidence relevant to the actual data and service. A contractual right is not an executed audit. Overdue actions and exceptions require accountable review of current exposure and interim measures. Keep metric definitions and changes transparent. Closing a ticket or buying a named product does not establish an outcome; test the actual treatment and record justified alternatives.')],
}

# The answer stays client-visible only for a deliberately ungraded formative aid.
# Practice keys continue to be withheld until server-side submission.
CHECKS = {
 'fundamentals': ('A branch test meets a database recovery time but excludes the identity service. What should the conclusion say?', ['All business recovery targets were met', 'The tested component recovered; end-to-end service recovery is unproven', 'Identity cannot affect recovery'], 1, 'A scoped component result is useful. The excluded dependency limits the service-level claim.'),
 'phishing': ('A familiar executive voice asks you to bypass payment approval. What should you do?', ['Transfer immediately', 'Ask for the same request in a personal chat', 'Use the established independent verification and approval process'], 2, 'Familiarity and another attacker-controlled message do not establish business authority.'),
 'identity': ('A password reset completes, but an exposed API token remains valid. What is needed?', ['Review and revoke the token through the supported process', 'Reset the same password again only', 'Declare all access removed'], 0, 'The token can represent a separate access path. Check its lifecycle rather than infer universal revocation.'),
 'network': ('A first-match firewall has a broad allow before a narrow deny. What should you validate?', ['Only the number of deny rules', 'Whether matching traffic is accepted before reaching the deny', 'Only the rule descriptions'], 1, 'Evaluation order and active placement determine enforcement, not the presence of a reassuring rule.'),
 'endpoint': ('A phone is reset before disposal. Is that enough evidence of sanitisation?', ['Always, regardless of device', 'Only if its case is clean', 'Validate the method for that device and storage'], 2, 'A reset label alone does not establish the residual-data outcome for every platform.'),
 'application': ('CSP is report-only. What has been achieved?', ['Observation of covered violations, not policy enforcement', 'All unwanted scripts are blocked', 'Server permissions are now correct'], 0, 'Report-only mode gathers reports; enforcement and safe rendering need their own verification.'),
 'cloud': ('A service stores essential data only on ephemeral instance storage. What is needed?', ['A new instance name', 'Review data lifetime and provide required persistence and recovery', 'Assume all cloud disks survive deletion'], 1, 'Storage lifetime is service-specific. A required record needs an explicit durable path.'),
 'response': ('An exercise triggers a rule but nobody receives the alert. What remains unproven?', ['That the test event existed', 'That every log is corrupt', 'End-to-end delivery and escalation'], 2, 'Detection capability includes the operational response chain after rule execution.'),
 'recovery': ('Failure occurs at noon; the last usable point is 11:30. What does thirty minutes describe?', ['The possible data-loss window, subject to other recovery records', 'The service restoration duration', 'Proof of zero data loss'], 0, 'Recovery-point age and restoration duration are different measures.'),
 'governance': ('An auditor samples only cases labelled successful by management. What should be considered?', ['That all successful cases are fraudulent', 'Selection bias and reconciliation to the full population', 'That the sample automatically represents every case'], 1, 'A filtered success set can omit failures. Define and validate the population before drawing conclusions.'),
}


def supplements(topic):
    prompt, options, answer, explanation = CHECKS[topic]
    readings = ([{'title': 'OWASP: ' + title, 'url': OWASP_ROOT + path, 'reviewed': REVIEW_DATE}
                 for title, path in APP_READINGS.values()] if topic == 'application' else [])
    return {'steps': [{'title': title, 'body': body} for title, body in TEACHING[topic]],
            'check': {'id': topic + '-check-v3', 'prompt': prompt, 'options': options,
                      'answer': answer, 'explanation': explanation}, 'extra_readings': readings}
